// Generated by Viscosity: "ps" stored as AoSoA, blocks of 8 (fields x, y, z).
class __Vsc_ps {
  constructor(cap = 16) { this.length = 0; this.cap = Math.ceil(cap / 8) * 8; this.data = new Float64Array(this.cap * 3); }
  static of(...v) { const c = new __Vsc_ps(v.length / 3); for (let i = 0; i < v.length; i += 3) c.push(v[i + 0], v[i + 1], v[i + 2]); return c; }
  push(v0, v1, v2) { const n = this.length; if (n === this.cap) this.grow(); const b = (n >> 3) * 24 + (n & 7); this.data[b + 0] = v0; this.data[b + 8] = v1; this.data[b + 16] = v2; return (this.length = n + 1); }
  grow() { const d = new Float64Array(this.cap * 2 * 3); d.set(this.data); this.data = d; this.cap *= 2; }
}
